import { defineConfig, devices } from '@playwright/test'
import { readFileSync } from 'fs'
import { resolve } from 'path'

/**
 * @see https://playwright.dev/docs/test-configuration
 */

// Load environment variables from .env.local if it exists
try {
  const envPath = resolve(process.cwd(), '.env.local')
  const envContent = readFileSync(envPath, 'utf-8')
  envContent.split('\n').forEach(line => {
    const trimmed = line.trim()
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=')
      if (key && valueParts.length > 0) {
        process.env[key] = valueParts.join('=')
      }
    }
  })
} catch (error) {
  // .env.local doesn't exist or can't be read, continue without it
}

// Check if we have authentication credentials available
const hasSupabaseCredentials = !!(process.env.VITE_SUPABASE_URL && process.env.VITE_SUPABASE_ANON_KEY)

export default defineConfig({
  testDir: './tests/e2e',
  /* Run tests in files in parallel */
  fullyParallel: true,
  /* Fail the build on CI if you accidentally left test.only in the source code. */
  forbidOnly: !!process.env.CI,
  /* One retry - fail fast */
  retries: 1,
  /* Opt out of parallel tests on CI. */
  workers: process.env.CI ? 1 : undefined,
  /* Reporter to use. See https://playwright.dev/docs/test-reporters */
  reporter: 'html',
  /* Shared settings for all the projects below. See https://playwright.dev/docs/api/class-testoptions. */
  use: {
    /* Base URL to use in actions like `await page.goto('/')`. */
    baseURL: 'http://localhost:5176',
    /* Collect trace when retrying the failed test. See https://playwright.dev/docs/trace-viewer */
    trace: 'on-first-retry',
    /* Set global timeout for actions like waitForSelector to 2 seconds */
    actionTimeout: 2000,
  },
  /* Global timeout for each test */
  timeout: 10000, // 10 seconds per test max

  /* Configure projects for major browsers */
  projects: [
    // Setup project - only run if we have Supabase credentials
    ...(hasSupabaseCredentials
      ? [{ name: 'setup', testMatch: /setup\/.*\.setup\.ts/ }]
      : []
    ),

    // Smoke tests - always run these (no authentication required)
    {
      name: 'chromium-smoke',
      use: { ...devices['Desktop Chrome'] },
      testMatch: /smoke\/.*\.spec\.ts/,
    },

    // Authenticated tests - only run if we have Supabase credentials
    ...(hasSupabaseCredentials ? [
      {
        name: 'chromium-pages',
        use: {
          ...devices['Desktop Chrome'],
          storageState: 'tests/.auth/user.json',
        },
        dependencies: ['setup'],
        testMatch: /pages\/.*\.spec\.ts/,
      },
      {
        name: 'chromium-components',
        use: {
          ...devices['Desktop Chrome'],
          storageState: 'tests/.auth/user.json',
        },
        dependencies: ['setup'],
        testMatch: /components\/.*\.spec\.ts/,
      },
      {
        name: 'chromium-flows',
        use: {
          ...devices['Desktop Chrome'],
          storageState: 'tests/.auth/user.json',
        },
        dependencies: ['setup'],
        testMatch: /flows\/.*\.spec\.ts/,
      },
      {
        name: 'chromium-navigation',
        use: {
          ...devices['Desktop Chrome'],
          storageState: 'tests/.auth/user.json',
        },
        dependencies: ['setup'],
        testMatch: /navigation\/.*\.spec\.ts/,
      }
    ] : []),

    // Additional browsers - only run locally and only for smoke tests in CI
    ...(process.env.CI ? [
      // In CI, only run smoke tests on additional browsers
      {
        name: 'firefox-smoke',
        use: { ...devices['Desktop Firefox'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },
    ] : [
      // Local development - run all browsers for smoke tests
      {
        name: 'firefox-smoke',
        use: { ...devices['Desktop Firefox'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },
      {
        name: 'webkit-smoke',
        use: { ...devices['Desktop Safari'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },
      {
        name: 'mobile-chrome-smoke',
        use: { ...devices['Pixel 5'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },
      {
        name: 'mobile-safari-smoke',
        use: { ...devices['iPhone 12'] },
        testMatch: /smoke\/.*\.spec\.ts/,
      },

      // Local authenticated tests on additional browsers (if credentials available)
      ...(hasSupabaseCredentials ? [
        {
          name: 'firefox-pages',
          use: {
            ...devices['Desktop Firefox'],
            storageState: 'tests/.auth/user.json',
          },
          dependencies: ['setup'],
          testMatch: /pages\/.*\.spec\.ts/,
        },
        {
          name: 'webkit-pages',
          use: {
            ...devices['Desktop Safari'],
            storageState: 'tests/.auth/user.json',
          },
          dependencies: ['setup'],
          testMatch: /pages\/.*\.spec\.ts/,
        },
      ] : [])
    ]),

    /* Test against branded browsers. */
    // {
    //   name: 'Microsoft Edge',
    //   use: { ...devices['Desktop Edge'], channel: 'msedge' },
    // },
    // {
    //   name: 'Google Chrome',
    //   use: { ...devices['Desktop Chrome'], channel: 'chrome' },
    // },
  ],

  /* Run your local dev server before starting the tests */
  webServer: {
    command: 'npm run dev -- --port 5176',
    url: 'http://localhost:5176',
    reuseExistingServer: !process.env.CI,
    timeout: 5 * 1000, // 5 seconds timeout for server startup
  },
})

import { lazy, Suspense } from 'react'
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom'
import { QueryClientProvider } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'
import { AuthProvider, useAuth } from './contexts/AuthContext'
import { SidebarProvider } from './contexts/SidebarContext'
import { ProtectedRoute } from './components/auth/ProtectedRoute'
import { AppLayout } from './components/layout/AppLayout'
import { Toaster } from './components/ui/toaster'
import { Skeleton } from './components/ui/skeleton'
import { queryClient } from './lib/queryClient'
import './App.css'

// Lazy load heavy pages for code splitting
const LoginForm = lazy(() => import('./components/auth/LoginForm').then(m => ({ default: m.LoginForm })))
const SignupForm = lazy(() => import('./components/auth/SignupForm').then(m => ({ default: m.SignupForm })))
const Dashboard = lazy(() => import('./pages/Dashboard').then(m => ({ default: m.Dashboard })))
const GearPage = lazy(() => import('./pages/GearPage').then(m => ({ default: m.GearPage })))
const ListsPage = lazy(() => import('./pages/ListsPage').then(m => ({ default: m.ListsPage })))
const ProfilePage = lazy(() => import('./pages/ProfilePage').then(m => ({ default: m.ProfilePage })))
const AccountPage = lazy(() => import('./pages/AccountPage').then(m => ({ default: m.AccountPage })))
const SettingsPage = lazy(() => import('./pages/SettingsPage').then(m => ({ default: m.SettingsPage })))

// Loading fallback component
function PageLoader() {
  return (
    <div className="min-h-screen bg-background flex items-center justify-center">
      <div className="space-y-4 w-full max-w-md">
        <Skeleton className="h-12 w-3/4 mx-auto" />
        <Skeleton className="h-64 w-full" />
        <Skeleton className="h-8 w-1/2 mx-auto" />
      </div>
    </div>
  )
}

function AppRoutes() {
  const { user } = useAuth()

  return (
    <Suspense fallback={<PageLoader />}>
      <Routes>
        {/* Public routes */}
        <Route 
          path="/login" 
          element={user ? <Navigate to="/" /> : <LoginForm />} 
        />
        <Route 
          path="/signup" 
          element={user ? <Navigate to="/" /> : <SignupForm />} 
        />

        {/* Protected routes wrapped in AppLayout */}
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <AppLayout>
                <Dashboard />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        {/* Keep /dashboard as alias for backwards compatibility */}
        <Route
          path="/dashboard"
          element={<Navigate to="/" replace />}
        />
        <Route
          path="/gear"
          element={
            <ProtectedRoute>
              <AppLayout>
                <GearPage />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/lists"
          element={
            <ProtectedRoute>
              <AppLayout>
                <ListsPage />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/profile"
          element={
            <ProtectedRoute>
              <AppLayout>
                <ProfilePage />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/account"
          element={
            <ProtectedRoute>
              <AppLayout>
                <AccountPage />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/settings"
          element={
            <ProtectedRoute>
              <AppLayout>
                <SettingsPage />
              </AppLayout>
            </ProtectedRoute>
          }
        />
      </Routes>
    </Suspense>
  )
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <Router>
        <AuthProvider>
          <SidebarProvider>
            <AppRoutes />
            <Toaster />
          </SidebarProvider>
        </AuthProvider>
      </Router>
      {/* Disabled TanStack devtools - obstructs mobile UI */}
      {/* {process.env.NODE_ENV === 'development' && !window.navigator.webdriver && <ReactQueryDevtools initialIsOpen={false} />} */}
    </QueryClientProvider>
  )
}

export default App

import { CollectionCompactRow, type CompactRowAction } from '@/components/shared/CollectionCompactRow'
import { Edit2, Trash2, Copy } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearCompactRowProps {
  item: GearItem
  weightUnit: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  onDuplicate?: (item: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'>) => void
  onClick?: (item: GearItem) => void
}

export function GearCompactRow({ 
  item, 
  weightUnit, 
  onEdit, 
  onDelete,
  onDuplicate,
  onClick 
}: GearCompactRowProps) {
  // Build subtitle from brand, model, and description (matches the screenshot format)
  const subtitle = [item.brand, item.model, item.description]
    .filter(Boolean)
    .join(', ')

  // Properties badges (compact version)
  const properties = (
    <div className="flex gap-1">
      {item.consumable && (
        <span className="text-xs text-muted-foreground">Consumable</span>
      )}
    </div>
  )

  // Data columns for compact view: Item Type, Weight, Properties  
  const columns = [
    item.item_type, // Item Type
    formatWeightWithUnit(item.weight_g, weightUnit), // Weight
    properties // Properties (Worn/Consumable)
  ]

  // Build actions
  const actions: CompactRowAction[] = [
    {
      label: 'Edit',
      icon: <Edit2 className="mr-2 h-4 w-4" />,
      onClick: () => onEdit(item)
    },
    ...(onDuplicate ? [{
      label: 'Duplicate',
      icon: <Copy className="mr-2 h-4 w-4" />,
      onClick: () => {
        const { id, created_at, updated_at, user_id, ...cloneData } = item
        const newItem = { ...cloneData, description: `${cloneData.description || 'Item'} (Copy)` }
        onDuplicate(newItem)
      }
    }] : []),
    {
      label: 'Delete',
      icon: <Trash2 className="mr-2 h-4 w-4" />,
      onClick: () => onDelete(item),
      variant: 'destructive' as const
    }
  ]

  return (
    <CollectionCompactRow
      title={item.description || 'Untitled Item'}
      subtitle={subtitle}
      columns={columns}
      actions={actions}
      onClick={onClick ? () => onClick(item) : undefined}
      url={item.url || undefined}
    />
  )
}

import { CollectionRow, type RowAction, type RowBadge } from '@/components/shared/CollectionRow'
import { Edit2, Trash2, Copy } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearRowProps {
  item: GearItem
  weightUnit: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  onDuplicate?: (item: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'>) => void
  onClick?: (item: GearItem) => void
  showProperties?: boolean // Whether to show the Properties column
}

export function GearRow({ 
  item, 
  weightUnit, 
  onEdit, 
  onDelete,
  onDuplicate,
  onClick,
  showProperties = true
}: GearRowProps) {
  // Build subtitle from model/description
  const subtitle = [item.model, item.description]
    .filter(Boolean)
    .join(' • ')

  // Build metadata for mobile - combine item_type and weight
  const weightDisplay = formatWeightWithUnit(item.weight_g, weightUnit)  
  const metadata = `${item.item_type} • ${weightDisplay}`

  // Build secondary info for desktop columns (Item Type, Weight, Properties?)
  const baseSecondaryInfo = [
    item.item_type, // Item Type column
    formatWeightWithUnit(item.weight_g, weightUnit) // Weight column
  ]

  const propertiesColumn = (
    <div className="flex items-center gap-1">
      {item.consumable && (
        <Badge variant="secondary" className="text-xs">
          Consumable
        </Badge>
      )}
    </div>
  )

  const secondaryInfo = showProperties 
    ? [...baseSecondaryInfo, propertiesColumn]
    : baseSecondaryInfo

  const columnClasses = showProperties 
    ? ['text-right', 'text-right', ''] // [Item Type, Weight, Properties]
    : ['text-right', 'text-right'] // [Item Type, Weight]

  // Build actions
  const actions: RowAction[] = [
    {
      label: 'Edit',
      icon: <Edit2 className="h-4 w-4" />,
      onClick: () => onEdit(item)
    },
    ...(onDuplicate ? [{
      label: 'Duplicate',
      icon: <Copy className="h-4 w-4" />,
      onClick: () => {
        const { id, created_at, updated_at, user_id, ...cloneData } = item
        const newItem = { ...cloneData, description: `${cloneData.description || 'Item'} (Copy)` }
        onDuplicate(newItem)
      }
    }] : []),
    {
      label: 'Delete',
      icon: <Trash2 className="h-4 w-4" />,
      onClick: () => onDelete(item),
      variant: 'destructive',
      separator: true
    }
  ]

  return (
    <CollectionRow
      title={item.description || 'Untitled Item'}
      subtitle={subtitle}
      brand={item.brand || undefined}
      metadata={metadata}
      secondaryInfo={secondaryInfo}
      columnClasses={columnClasses}
      actions={actions}
      onClick={onClick ? () => onClick(item) : undefined}
      url={item.url || undefined}
    />
  )
}

