import { useState } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { MobileFormDrawer } from '@/components/ui/mobile-form-drawer'
// Button is used in MobileFormDrawer primaryAction
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
// Using simple checkbox for now - could add shadcn checkbox later
import { Search, Package, Weight } from 'lucide-react'
import { useAddMultipleGearToList } from '@/hooks/useListData'
import { formatWeightWithUnit } from '@/utils/weight'
import type { List, GearItem, WeightUnit } from '@/types/database'

interface AddGearToListFormProps {
  list: List
  availableGearItems: GearItem[]
  weightUnit?: WeightUnit
  onClose: () => void
}

export function AddGearToListForm({ 
  list, 
  availableGearItems, 
  weightUnit = 'g',
  onClose 
}: AddGearToListFormProps) {
  const { user } = useAuth()
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedItems, setSelectedItems] = useState<Set<string>>(new Set())

  const addGearMutation = useAddMultipleGearToList(user?.id)

  const filteredItems = availableGearItems.filter(item =>
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.brand?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.category.toLowerCase().includes(searchTerm.toLowerCase())
  )

  const handleItemToggle = (itemId: string) => {
    const newSelected = new Set(selectedItems)
    if (newSelected.has(itemId)) {
      newSelected.delete(itemId)
    } else {
      newSelected.add(itemId)
    }
    setSelectedItems(newSelected)
  }

  const handleAddSelected = async () => {
    if (selectedItems.size === 0) return

    try {
      // Use bulk operation for better performance
      const selectedIds = Array.from(selectedItems)
      await addGearMutation.mutateAsync({
        listId: list.id,
        gearIds: selectedIds
      })
      onClose()
    } catch (error) {
      // Error is handled by the mutation
    }
  }

  const selectedCount = selectedItems.size
  const hasAvailableItems = availableGearItems.length > 0

  return (
    <MobileFormDrawer
      isOpen={true}
      onClose={onClose}
      title={`Add Gear to ${list.name}`}
      primaryAction={{
        label: `Add ${selectedCount} Item${selectedCount !== 1 ? 's' : ''}`,
        onClick: handleAddSelected,
        disabled: selectedCount === 0,
        loading: addGearMutation.isPending
      }}
      secondaryAction={{
        label: 'Cancel',
        onClick: onClose
      }}
    >
      <div className="p-6 space-y-6">
        {!hasAvailableItems ? (
          <div className="text-center py-8">
            <Package className="mx-auto h-12 w-12 text-muted-foreground/30 mb-4" />
            <h3 className="text-lg font-medium mb-2">All gear already added</h3>
            <p className="text-sm text-muted-foreground">
              Every item in your gear library is already part of this list.
            </p>
          </div>
        ) : (
          <>
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                type="text"
                placeholder="Search gear..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>

            {/* Stats */}
            <div className="text-sm text-muted-foreground">
              {filteredItems.length} of {availableGearItems.length} items available
              {selectedCount > 0 && ` • ${selectedCount} selected`}
            </div>

            {/* Items List */}
            <div className="space-y-2 max-h-96 overflow-y-auto">
              {filteredItems.length === 0 ? (
                <div className="text-center py-8">
                  <Package className="mx-auto h-8 w-8 text-muted-foreground/30 mb-2" />
                  <p className="text-sm text-muted-foreground">
                    {searchTerm ? 'No gear matches your search' : 'No gear available'}
                  </p>
                </div>
              ) : (
                filteredItems.map((item) => (
                  <div
                    key={item.id}
                    className="flex items-start space-x-3 p-3 border rounded-lg hover:bg-muted/50 cursor-pointer"
                    onClick={() => handleItemToggle(item.id)}
                  >
                    <input
                      type="checkbox"
                      checked={selectedItems.has(item.id)}
                      onChange={() => handleItemToggle(item.id)}
                      className="mt-1 h-4 w-4 text-primary border-border rounded focus:ring-primary"
                    />

                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <div className="flex-1 min-w-0">
                          <h4 className="font-medium text-sm leading-5">{item.name}</h4>
                          {item.brand && (
                            <p className="text-xs text-muted-foreground mt-0.5">{item.brand}</p>
                          )}
                        </div>

                        <div className="flex items-center gap-2 text-xs text-muted-foreground">
                          <Weight className="h-3 w-3" />
                          <span>{formatWeightWithUnit(item.weight_grams, weightUnit)}</span>
                          {item.quantity > 1 && (
                            <span>× {item.quantity}</span>
                          )}
                        </div>
                      </div>

                      <div className="flex items-center gap-2 mt-2">
                        <Badge variant="outline" className="text-xs">
                          {item.category}
                        </Badge>
                        {item.worn && (
                          <Badge variant="secondary" className="text-xs">
                            Worn
                          </Badge>
                        )}
                        {item.consumable && (
                          <Badge variant="secondary" className="text-xs">
                            Consumable
                          </Badge>
                        )}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </>
        )}
      </div>
    </MobileFormDrawer>
  )
}

import { CollectionRow, type RowAction, type RowBadge } from '@/components/shared/CollectionRow'
import { Edit2, Trash2, Copy, Eye } from 'lucide-react'
import type { List, GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface ListRowProps {
  list: List
  gearItems: GearItem[]
  weightUnit: WeightUnit
  onView: (list: List) => void
  onEdit: (list: List) => void
  onDelete: (list: List) => void
  onDuplicate: (list: List) => void
}

export function ListRow({ 
  list, 
  gearItems,
  weightUnit,
  onView,
  onEdit, 
  onDelete,
  onDuplicate
}: ListRowProps) {
  // Calculate list stats
  const listGear = gearItems.filter(item => list.gear_ids.includes(item.id))
  const totalWeight = listGear.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)

  // No category column for lists (activity type will show in mobile metadata only)

  // Build metadata for mobile
  const itemCount = list.gear_ids.length
  const itemText = itemCount === 1 ? 'item' : 'items'
  const weightDisplay = totalWeight > 0 
    ? formatWeightWithUnit(totalWeight, weightUnit)
    : '0g'

  // Mobile metadata shows item count and weight
  const metadataParts = [
    `${itemCount} ${itemText}`,
    weightDisplay
  ]
  const metadata = metadataParts.join(' • ')

  // For lists, show item count and weight in secondary columns
  const secondaryInfo = [
    itemCount,
    weightDisplay
  ]

  const columnClasses = ['text-right', 'text-right font-medium']

  // Build actions
  const actions: RowAction[] = [
    {
      label: 'View',
      icon: <Eye className="h-4 w-4" />,
      onClick: () => onView(list)
    },
    {
      label: 'Edit',
      icon: <Edit2 className="h-4 w-4" />,
      onClick: () => onEdit(list)
    },
    {
      label: 'Duplicate',
      icon: <Copy className="h-4 w-4" />,
      onClick: () => onDuplicate(list)
    },
    {
      label: 'Delete',
      icon: <Trash2 className="h-4 w-4" />,
      onClick: () => onDelete(list),
      variant: 'destructive',
      separator: true
    }
  ]

  return (
    <CollectionRow
      title={list.name}
      subtitle={list.description}
      metadata={metadata}
      secondaryInfo={secondaryInfo}
      columnClasses={columnClasses}
      actions={actions}
      onClick={() => onView(list)}
    />
  )
}

