import { useRef, useState, useCallback } from 'react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { Progress } from '@/components/ui/progress'
import { Camera, Upload, X, Loader2, Image as ImageIcon } from 'lucide-react'
import { AvatarValidation } from '@/utils/formValidation'
import { cn } from '@/lib/utils'

interface AvatarUploadProps {
  currentAvatarUrl?: string | null
  displayName: string
  onUpload?: (file: File) => void | Promise<void>
  onDelete?: () => void | Promise<void>
  isUploading?: boolean
  uploadProgress?: number
  disabled?: boolean
  compact?: boolean
}

export function AvatarUpload({
  currentAvatarUrl,
  displayName,
  onUpload,
  onDelete,
  isUploading = false,
  uploadProgress = 0,
  disabled = false,
  compact = false
}: AvatarUploadProps) {
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [previewUrl, setPreviewUrl] = useState<string | null>(null)

  const getInitials = (name: string) => {
    return name
      .split(' ')
      .map(n => n[0])
      .filter(Boolean)
      .slice(0, 2)
      .join('')
      .toUpperCase()
  }

  const handleFileSelect = useCallback(async (file: File) => {
    setError(null)

    // Validate file
    const validationError = AvatarValidation.validate(file)
    if (validationError) {
      setError(validationError)
      return
    }

    // Create preview
    const reader = new FileReader()
    reader.onloadend = () => {
      setPreviewUrl(reader.result as string)
    }
    reader.readAsDataURL(file)

    // Upload file
    if (onUpload) {
      try {
        await onUpload(file)
        setPreviewUrl(null) // Clear preview after successful upload
      } catch (err) {
        setError('Failed to upload image. Please try again.')
        setPreviewUrl(null)
      }
    }
  }, [onUpload])

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      handleFileSelect(file)
    }
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    if (!disabled && !isUploading) {
      setIsDragging(true)
    }
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDragging(false)
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDragging(false)

    if (disabled || isUploading) return

    const file = e.dataTransfer.files?.[0]
    if (file && file.type.startsWith('image/')) {
      handleFileSelect(file)
    }
  }

  const handleUploadClick = () => {
    fileInputRef.current?.click()
  }

  const avatarUrl = previewUrl || currentAvatarUrl

  // Compact layout for edit mode
  if (compact) {
    return (
      <div className="flex items-center gap-4 w-full">
        {/* Smaller Avatar */}
        <div
          className={cn(
            "relative rounded-full transition-all duration-200 flex-shrink-0",
            isDragging && "scale-105",
            !disabled && !isUploading && "group"
          )}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
        >
          {/* Drag indicator overlay */}
          {isDragging && (
            <div className="absolute inset-0 z-10 flex items-center justify-center rounded-full bg-primary/20 backdrop-blur-sm">
              <Upload className="h-5 w-5" />
            </div>
          )}

          {/* Smaller Avatar for compact mode */}
          <Avatar className="h-20 w-20 border-2 border-background shadow">
            <AvatarImage 
              src={avatarUrl || undefined} 
              alt={displayName || 'Avatar'}
            />
            <AvatarFallback className="text-lg bg-muted">
              {getInitials(displayName || 'U')}
            </AvatarFallback>
          </Avatar>

          {/* Hover overlay */}
          {avatarUrl && !disabled && !isUploading && (
            <div className="absolute inset-0 flex items-center justify-center rounded-full bg-black/60 opacity-0 transition-opacity group-hover:opacity-100">
              <Camera className="h-6 w-6 text-white" />
            </div>
          )}

          {/* Upload progress overlay */}
          {isUploading && (
            <div className="absolute inset-0 flex items-center justify-center rounded-full bg-black/60">
              <Loader2 className="h-6 w-6 animate-spin text-white" />
            </div>
          )}
        </div>

        {/* Upload controls */}
        <div className="flex-1 space-y-2">
          <div className="flex gap-2">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={handleUploadClick}
              disabled={disabled || isUploading}
            >
              <Upload className="mr-2 h-4 w-4" />
              {avatarUrl ? 'Change' : 'Upload'} Photo
            </Button>
            {avatarUrl && onDelete && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={onDelete}
                disabled={disabled || isUploading}
              >
                <X className="mr-2 h-4 w-4" />
                Remove
              </Button>
            )}
          </div>
          <p className="text-xs text-muted-foreground">
            JPG, PNG or WebP. Max 5MB
          </p>
          {/* Upload progress bar */}
          {isUploading && uploadProgress > 0 && (
            <Progress value={uploadProgress} className="h-1" />
          )}
          {/* Error message */}
          {error && (
            <p className="text-xs text-destructive" role="alert">
              {error}
            </p>
          )}
        </div>

        {/* Hidden file input */}
        <input
          ref={fileInputRef}
          type="file"
          accept="image/jpeg,image/jpg,image/png,image/webp"
          onChange={handleFileChange}
          className="sr-only"
          disabled={disabled || isUploading}
          aria-label="Upload avatar image"
        />
      </div>
    )
  }

  // Original full-size layout for profile preview
  return (
    <div className="space-y-4">
      {/* Avatar with upload zone */}
      <div
        className={cn(
          "relative mx-auto w-fit rounded-full transition-all duration-200",
          isDragging && "scale-105",
          !disabled && !isUploading && "group"
        )}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        {/* Drag indicator overlay */}
        {isDragging && (
          <div className="absolute inset-0 z-10 flex items-center justify-center rounded-full bg-primary/20 backdrop-blur-sm">
            <div className="rounded-lg bg-background/90 px-3 py-2 shadow-lg">
              <Upload className="h-6 w-6" />
            </div>
          </div>
        )}

        {/* Avatar */}
        <Avatar className="h-32 w-32 border-4 border-background shadow-lg">
          <AvatarImage 
            src={avatarUrl || undefined} 
            alt={displayName || 'Avatar'}
          />
          <AvatarFallback className="text-2xl bg-muted">
            {getInitials(displayName || 'U')}
          </AvatarFallback>
        </Avatar>

        {/* Hover overlay for existing avatar */}
        {avatarUrl && !disabled && !isUploading && (
          <div className="absolute inset-0 flex items-center justify-center rounded-full bg-black/60 opacity-0 transition-opacity group-hover:opacity-100">
            <Camera className="h-8 w-8 text-white" />
          </div>
        )}

        {/* Upload progress overlay */}
        {isUploading && (
          <div className="absolute inset-0 flex items-center justify-center rounded-full bg-black/60">
            <div className="text-center">
              <Loader2 className="mx-auto h-8 w-8 animate-spin text-white" />
              {uploadProgress > 0 && (
                <p className="mt-2 text-xs text-white">{uploadProgress}%</p>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Upload progress bar */}
      {isUploading && uploadProgress > 0 && (
        <Progress value={uploadProgress} className="h-1" />
      )}

      {/* Action buttons */}
      <div className="flex flex-col items-center space-y-3">
        {!avatarUrl ? (
          <Button
            type="button"
            variant="outline"
            onClick={handleUploadClick}
            disabled={disabled || isUploading}
            className="min-h-[44px]"
          >
            <ImageIcon className="mr-2 h-4 w-4" />
            Upload Photo
          </Button>
        ) : (
          <div className="flex gap-2">
            <Button
              type="button"
