import { useState, useEffect, useRef, useMemo } from 'react'
import { Button } from '@/components/ui/button'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { FormField, EnhancedInput, EnhancedTextarea } from '@/components/ui/form-field'
import { FormActionButtons } from '@/components/shared/FormActionButtons'
import { getCharacterCount } from '@/utils/formValidation'
import { AvatarUpload } from './AvatarUpload'
import { Lightbulb } from 'lucide-react'
import { useCheckUsernameAvailability, useValidateUsername } from '@/hooks/useProfileData'
import type { ProfileFormData, UserProfile } from '@/types/database'
import { useDebounce } from '@/hooks/useDebounce'
import { generateUsernameSuggestions } from '@/utils/usernameSuggestions'

interface ProfileFormProps {
  profile?: UserProfile | null
  onSubmit: (data: ProfileFormData) => void | Promise<void>
  onCancel: () => void
  onAvatarUpload?: (file: File) => void | Promise<void>
  onAvatarDelete?: () => void | Promise<void>
  isLoading?: boolean
  standalone?: boolean
  onDirtyStateChange?: (isDirty: boolean) => void
}

export function ProfileForm({
  profile,
  onSubmit,
  onCancel,
  onAvatarUpload,
  onAvatarDelete,
  isLoading = false,
  standalone = true,
  onDirtyStateChange
}: ProfileFormProps) {
  const validateUsername = useValidateUsername()

  // Initial form state for comparison
  const initialFormData = useRef<ProfileFormData>({
    username: profile?.username || '',
    display_name: profile?.display_name || '',
    location: profile?.location || '',
    about_me: profile?.about_me || ''
  })

  // Form state
  const [formData, setFormData] = useState<ProfileFormData>(initialFormData.current)

  const [errors, setErrors] = useState<Partial<Record<keyof ProfileFormData, string>>>({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isUploadingAvatar, setIsUploadingAvatar] = useState(false)
  const [uploadProgress, setUploadProgress] = useState(0)

  // Username validation state
  const [usernameInput, setUsernameInput] = useState(formData.username)
  const [usernameSuggestions, setUsernameSuggestions] = useState<string[]>([])
  const debouncedUsername = useDebounce(usernameInput, 500)

  // Check username availability
  const { data: isAvailable, isLoading: isCheckingUsername } = useCheckUsernameAvailability(
    debouncedUsername,
    profile?.user_id, // Exclude current user when editing
    debouncedUsername !== profile?.username && debouncedUsername.length >= 3
  )

  // Calculate if form has been modified
  const isDirty = useMemo(() => {
    return JSON.stringify(formData) !== JSON.stringify(initialFormData.current)
  }, [formData])

  // Notify parent component of dirty state changes
  useEffect(() => {
    onDirtyStateChange?.(isDirty)
  }, [isDirty, onDirtyStateChange])

  // Update form data when username changes
  useEffect(() => {
    setFormData(prev => ({ ...prev, username: usernameInput }))
  }, [usernameInput])

  // Generate username suggestions when a username is taken
  useEffect(() => {
    if (isAvailable === false && debouncedUsername.length >= 3 && debouncedUsername !== profile?.username) {
      const suggestions = generateUsernameSuggestions(debouncedUsername)
      setUsernameSuggestions(suggestions)
    } else {
      setUsernameSuggestions([])
    }
  }, [isAvailable, debouncedUsername, profile?.username])

  // Real-time username availability error handling
  useEffect(() => {
    if (debouncedUsername.length >= 3 && debouncedUsername !== profile?.username) {
      if (isAvailable === false) {
        setErrors(prev => ({ ...prev, username: 'Username is already taken' }))
      } else if (isAvailable === true) {
        // Clear username error if it was a availability error
        setErrors(prev => {
          const newErrors = { ...prev }
          if (newErrors.username === 'Username is already taken') {
            delete newErrors.username
          }
          return newErrors
        })
      }
    }
  }, [isAvailable, debouncedUsername, profile?.username])

  // Validate form
  const validateForm = (): boolean => {
    const newErrors: Partial<Record<keyof ProfileFormData, string>> = {}

    // Username validation
    const usernameError = validateUsername(formData.username)
    if (usernameError) {
      newErrors.username = usernameError
    } else if (formData.username !== profile?.username && isAvailable === false) {
      newErrors.username = 'Username is already taken'
    }

    // Display name validation
    if (!formData.display_name.trim()) {
      newErrors.display_name = 'Display name is required'
    } else if (formData.display_name.length > 50) {
      newErrors.display_name = 'Display name must be 50 characters or less'
    }

    // Location validation
    if (formData.location && formData.location.length > 100) {
      newErrors.location = 'Location must be 100 characters or less'
    }

    // About me validation
    if (formData.about_me && formData.about_me.length > 500) {
      newErrors.about_me = 'About me must be 500 characters or less'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) return

    setIsSubmitting(true)
    try {
      await onSubmit(formData)
      // Reset initial form data after successful save
      initialFormData.current = formData
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleSuggestionClick = (suggestion: string) => {
    setUsernameInput(suggestion)
    setUsernameSuggestions([])
  }

  const handleAvatarUpload = async (file: File) => {
    if (!onAvatarUpload) return

    setIsUploadingAvatar(true)
    setUploadProgress(0)
    try {
      // TODO: Replace with actual upload progress tracking when backend supports it
      // Simulate progress for demo (in real app, track actual upload progress)
      const progressInterval = setInterval(() => {
        setUploadProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval)
            return 90
          }
          return prev + 10
        })
      }, 100)

      await onAvatarUpload(file)
      clearInterval(progressInterval)
      setUploadProgress(100)

      // Clear progress after a short delay
      setTimeout(() => setUploadProgress(0), 500)
    } catch (error) {
      console.error('Failed to upload avatar:', error)
      setUploadProgress(0)
    } finally {
      setIsUploadingAvatar(false)
    }
  }

  const handleAvatarDelete = async () => {
    if (!onAvatarDelete) return

    setIsUploadingAvatar(true)
    try {
      await onAvatarDelete()
    } finally {
      setIsUploadingAvatar(false)
    }
  }

  const getInitials = (_name: string) => {
    return name
      .split(' ')
      .map(n => n[0])
      .filter(Boolean)
      .slice(0, 2)
      .join('')
      .toUpperCase()
  }

  return (
    <form 
      onSubmit={handleSubmit} 
      data-profile-form 
      className={standalone ? "space-y-4" : "space-y-3 px-3 py-2"}
      aria-label="Profile form"
      noValidate>
      {/* Compact Avatar Section */}
      <section className={`flex items-center gap-4 ${standalone ? 'pb-4' : 'pb-3'} border-b border-border/20`}>
        <AvatarUpload
          currentAvatarUrl={profile?.avatar_url}
          displayName={formData.display_name || 'User'}
          onUpload={handleAvatarUpload}
          onDelete={onAvatarDelete ? handleAvatarDelete : undefined}
          isUploading={isUploadingAvatar}
          uploadProgress={uploadProgress}
          disabled={isLoading}
          compact={true}
        />
      </section>

      {/* Form Fields */}
      <section className="space-y-3">
        {/* Username & Display Name - Two columns on desktop */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {/* Username */}
          <FormField
            label="Username"
            htmlFor="username"
            required
            error={errors.username}
            success={!errors.username && !isCheckingUsername && debouncedUsername.length >= 3 && isAvailable === true}
            helperText={
              isCheckingUsername ? 'Checking availability...' :
              (!errors.username && debouncedUsername.length >= 3 && isAvailable === true) ? 'Username is available' :
              (!errors.username ? 'Letters, numbers, underscores' : undefined)
            }
          >
            <EnhancedInput
              id="username"
              value={usernameInput}
              onChange={(e) => setUsernameInput(e.target.value)}
              placeholder="johndoe"
              error={!!errors.username}
              success={!errors.username && !isCheckingUsername && debouncedUsername.length >= 3 && isAvailable === true}
              loading={isCheckingUsername && debouncedUsername.length >= 3}
              disabled={isLoading}
              aria-invalid={!!errors.username}
              aria-describedby={errors.username ? 'username-error' : 'username-hint'}
              aria-required="true"
            />
          </FormField>

          {/* Display Name */}
          <FormField
            label="Display Name"
            htmlFor="display_name"
            required
            error={errors.display_name}
            helperText={!errors.display_name ? 'Your public name' : undefined}
          >
            <EnhancedInput
              id="display_name"
              value={formData.display_name}
              onChange={(e) => setFormData(prev => ({ ...prev, display_name: e.target.value }))}
              placeholder="John Doe"
              error={!!errors.display_name}
              disabled={isLoading}
              aria-required="true"
            />
          </FormField>
        </div>

        {/* Username suggestions */}
        {usernameSuggestions.length > 0 && (
          <Alert className="mt-2">
            <Lightbulb className="h-4 w-4" />
            <AlertDescription>
              <p className="mb-2 font-medium">Username taken. Try one of these:</p>
              <div className="flex flex-wrap gap-2">
                {usernameSuggestions.map((suggestion) => (
                  <Button
                    key={suggestion}
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => handleSuggestionClick(suggestion)}
                    className="text-xs"
                  >
                    {suggestion}
                  </Button>
                ))}
              </div>
            </AlertDescription>
          </Alert>
        )}

        {/* Location - Full width */}
        <FormField
          label="Location"
          htmlFor="location"
          error={errors.location}
          helperText={!errors.location ? 'City, State or Country' : undefined}
        >
          <EnhancedInput
            id="location"
            value={formData.location || ''}
            onChange={(e) => setFormData(prev => ({ ...prev, location: e.target.value }))}
            placeholder="San Francisco, CA"
            error={!!errors.location}
            disabled={isLoading}
          />
        </FormField>

        {/* About Me with inline character count */}
        <FormField
          label="About Me"
          htmlFor="about_me"
          error={errors.about_me}
          helperText={
            !errors.about_me ? (
              <span className={`${
                getCharacterCount(formData.about_me || '', 500).isNearLimit 
                  ? 'text-orange-500' 
                  : ''
              }`}>
                {getCharacterCount(formData.about_me || '', 500).display}
              </span>
            ) : undefined
          }
        >
          <EnhancedTextarea
            id="about_me"
            value={formData.about_me || ''}
            onChange={(e) => setFormData(prev => ({ ...prev, about_me: e.target.value }))}
            placeholder="Tell us about yourself and your outdoor adventures..."
            error={!!errors.about_me}
            disabled={isLoading}
            rows={standalone ? 3 : 2}
          />
        </FormField>
      </section>

      {/* Form Actions - Sticky on mobile */}
      {standalone && (
        <div className="pt-2 md:pt-4 sticky bottom-0 bg-background pb-4 md:static md:bg-transparent md:pb-0">
          <FormActionButtons
            onCancel={onCancel}
            isLoading={isSubmitting || isLoading || isCheckingUsername}
            saveText="Save Profile"
            disabled={!isDirty || isSubmitting || isLoading || isCheckingUsername}
          />
        </div>
      )}
    </form>
  )
}

