import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { createGearRepository } from '@/lib/gearRepository'
import { queryKeys } from '@/lib/queryClient'
import type { GearItem } from '@/types/database'
import { toast } from './use-toast'
import { captureError } from '@/lib/sentry'

// Hook to fetch all gear items with caching
export function useGearItems(userId: string | undefined) {
  return useQuery({
    queryKey: queryKeys.gearList(userId || ''),
    queryFn: async () => {
      if (!userId) throw new Error('User ID required')
      const repo = createGearRepository(userId)
      return repo.list()
    },
    enabled: !!userId,
  })
}

// Hook to fetch gear count
export function useGearCount(userId: string | undefined) {
  return useQuery({
    queryKey: queryKeys.gearCount(userId || ''),
    queryFn: async () => {
      if (!userId) throw new Error('User ID required')
      const repo = createGearRepository(userId)
      return repo.count()
    },
    enabled: !!userId,
  })
}

// Hook to create gear with optimistic updates
export function useCreateGear(userId: string | undefined) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
      if (!userId) throw new Error('User ID required')
      const repo = createGearRepository(userId)
      return repo.create(gear)
    },
    onMutate: async (newGear) => {
      if (!userId) return

      // Cancel any outgoing refetches
      await queryClient.cancelQueries({ queryKey: queryKeys.gearList(userId) })

      // Snapshot the previous value
      const previousGear = queryClient.getQueryData<GearItem[]>(queryKeys.gearList(userId))

      // Optimistically update with a temporary item
      const tempItem: GearItem = {
        ...newGear,
        id: `temp-${crypto.randomUUID()}`,
        user_id: userId,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      }

      queryClient.setQueryData<GearItem[]>(queryKeys.gearList(userId), (old) => 
        [...(old || []), tempItem]
      )

      // Update count optimistically
      queryClient.setQueryData<number>(queryKeys.gearCount(userId), (old) => 
        (old || 0) + 1
      )

      // Return context for rollback
      return { previousGear, tempItem }
    },
    onSuccess: (newItem, _, context) => {
      if (!userId || !context) return

      // Replace temp item with real item
      queryClient.setQueryData<GearItem[]>(queryKeys.gearList(userId), (old) => 
        old?.map(item => item.id === context.tempItem.id ? newItem : item) || []
      )

      toast.success(`✓ ${newItem.name} added to your gear closet`)
    },
    onError: (error, _, context) => {
      if (!userId) return

      // Rollback on error
      if (context?.previousGear) {
        queryClient.setQueryData(queryKeys.gearList(userId), context.previousGear)
        queryClient.setQueryData<number>(queryKeys.gearCount(userId), (old) => 
          Math.max(0, (old || 0) - 1)
        )
      }

      captureError(error as Error, {
        component: 'useCreateGear',
        action: 'create'
      })
      toast.error('Failed to add gear', 'Please try again.')
    },
    onSettled: () => {
      if (!userId) return
      // Ensure data is in sync after mutation
      queryClient.invalidateQueries({ queryKey: queryKeys.gearList(userId) })
      queryClient.invalidateQueries({ queryKey: queryKeys.gearCount(userId) })
    },
  })
}

// Hook to update gear with optimistic updates
export function useUpdateGear(userId: string | undefined) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async ({ 
      id, 
      updates 
    }: { 
      id: string
      updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>> 
    }) => {
      if (!userId) throw new Error('User ID required')
      const repo = createGearRepository(userId)
      return repo.update(id, updates)
    },
    onMutate: async ({ id, updates }) => {
      if (!userId) return

      // Cancel any outgoing refetches
      await queryClient.cancelQueries({ queryKey: queryKeys.gearList(userId) })

      // Snapshot the previous value
      const previousGear = queryClient.getQueryData<GearItem[]>(queryKeys.gearList(userId))

      // Optimistically update
      queryClient.setQueryData<GearItem[]>(queryKeys.gearList(userId), (old) => 
        old?.map(item => item.id === id 
          ? { ...item, ...updates, updated_at: new Date().toISOString() }
          : item
        ) || []
      )

      // Return context for rollback
      return { previousGear }
    },
    onSuccess: () => {
      toast.success('Gear updated successfully')
    },
    onError: (error, _, context) => {
      if (!userId) return

      // Rollback on error
      if (context?.previousGear) {
        queryClient.setQueryData(queryKeys.gearList(userId), context.previousGear)
      }

      captureError(error as Error, {
        component: 'useUpdateGear',
        action: 'update'
      })
      toast.error('Failed to update gear', 'Please try again.')
    },
    onSettled: () => {
      if (!userId) return
      // Ensure data is in sync after mutation
      queryClient.invalidateQueries({ queryKey: queryKeys.gearList(userId) })
    },
  })
}

// Hook to delete gear with optimistic updates and undo
export function useDeleteGear(userId: string | undefined) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (id: string) => {
      if (!userId) throw new Error('User ID required')
      const repo = createGearRepository(userId)
      await repo.delete(id)
      return id
    },
    onMutate: async (id) => {
      if (!userId) return

      // Cancel any outgoing refetches
      await queryClient.cancelQueries({ queryKey: queryKeys.gearList(userId) })

      // Snapshot the previous value
      const previousGear = queryClient.getQueryData<GearItem[]>(queryKeys.gearList(userId))
      const deletedItem = previousGear?.find(item => item.id === id)

      // Optimistically remove the item
      queryClient.setQueryData<GearItem[]>(queryKeys.gearList(userId), (old) => 
        old?.filter(item => item.id !== id) || []
      )

      // Update count optimistically
      queryClient.setQueryData<number>(queryKeys.gearCount(userId), (old) => 
        Math.max(0, (old || 0) - 1)
      )

      // Return context for rollback and potential undo
      return { previousGear, deletedItem }
    },
    onSuccess: (_, __, context) => {
      if (!context?.deletedItem) {
        toast.success('Item deleted successfully')
        return
      }

      // Store the deleted item data for undo (without the problematic async onClick)
      const deletedItemData = context.deletedItem
      const itemName = deletedItemData.name

      // Show simple success toast without complex action
      toast.success(`${itemName} deleted successfully`)

      // TODO: In the future, implement undo with a proper state management solution
    },
    onError: (error, _, context) => {
      if (!userId) return

      // Rollback on error
      if (context?.previousGear) {
        queryClient.setQueryData(queryKeys.gearList(userId), context.previousGear)
        queryClient.setQueryData<number>(queryKeys.gearCount(userId), (old) => 
          (old || 0) + 1
        )
      }

      captureError(error as Error, {
        component: 'useDeleteGear',
        action: 'delete'
      })
      toast.error('Failed to delete gear', 'Please try again.')
    },
    onSettled: () => {
      if (!userId) return
      // Ensure data is in sync after mutation
      queryClient.invalidateQueries({ queryKey: queryKeys.gearList(userId) })
      queryClient.invalidateQueries({ queryKey: queryKeys.gearCount(userId) })
    },
  })
}

// Hook to restore a deleted item (undo)
export function useRestoreGear(userId: string | undefined) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (item: Omit<GearItem, 'id' | 'created_at' | 'updated_at'>) => {
      if (!userId) throw new Error('User ID required')
      const repo = createGearRepository(userId)
      // Remove user_id from the item data before creating
      const { user_id, ...itemData } = item as any
      return repo.create(itemData)
    },
    onMutate: async (item) => {
      if (!userId) return

      // Cancel any outgoing refetches
      await queryClient.cancelQueries({ queryKey: queryKeys.gearList(userId) })

      // Get current data
      const previousGear = queryClient.getQueryData<GearItem[]>(queryKeys.gearList(userId))

      // Optimistically add the item back
      const tempItem: GearItem = {
        ...item,
        id: `temp-restore-${Date.now()}`,
        user_id: userId,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } as GearItem

      queryClient.setQueryData<GearItem[]>(queryKeys.gearList(userId), (old) => 
        [...(old || []), tempItem]
      )

      // Update count optimistically
      queryClient.setQueryData<number>(queryKeys.gearCount(userId), (old) => 
        (old || 0) + 1
      )

      return { previousGear, tempItem }
    },
    onSuccess: (newItem, _, context) => {
      if (!userId || !context) return

      // Replace temp item with real item
      queryClient.setQueryData<GearItem[]>(queryKeys.gearList(userId), (old) => 
        old?.map(item => item.id === context.tempItem.id ? newItem : item) || []
      )

      toast.success('Item restored')
    },
    onError: (error, _, context) => {
      if (!userId) return

      // Rollback on error
      if (context?.previousGear) {
        queryClient.setQueryData(queryKeys.gearList(userId), context.previousGear)
        queryClient.setQueryData<number>(queryKeys.gearCount(userId), (old) => 
          Math.max(0, (old || 0) - 1)
        )
      }

      captureError(error as Error, {
        component: 'useRestoreGear',
        action: 'restore'
      })
      toast.error('Failed to restore item')
    },
    onSettled: () => {
      if (!userId) return
      // Ensure data is in sync
      queryClient.invalidateQueries({ queryKey: queryKeys.gearList(userId) })
      queryClient.invalidateQueries({ queryKey: queryKeys.gearCount(userId) })
    },
  })
}

// Hook for bulk create (import)
export function useBulkCreateGear(userId: string | undefined) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (items: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>[]) => {
      if (!userId) throw new Error('User ID required')
      const repo = createGearRepository(userId)
      return repo.createMany(items)
    },
    onMutate: async (newItems) => {
      if (!userId) return

      // Cancel any outgoing refetches
      await queryClient.cancelQueries({ queryKey: queryKeys.gearList(userId) })

      // Snapshot the previous value
      const previousGear = queryClient.getQueryData<GearItem[]>(queryKeys.gearList(userId))

      // Optimistically add items with temporary IDs
      const tempItems: GearItem[] = newItems.map((item, index) => ({
        ...item,
        id: `temp-bulk-${crypto.randomUUID()}`,
        user_id: userId,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      }))

      queryClient.setQueryData<GearItem[]>(queryKeys.gearList(userId), (old) => 
        [...(old || []), ...tempItems]
      )

      // Update count optimistically
      queryClient.setQueryData<number>(queryKeys.gearCount(userId), (old) => 
        (old || 0) + newItems.length
      )

      // Return context for rollback
      return { previousGear, tempItems }
    },
    onSuccess: (newItems, originalItems, context) => {
      if (!userId || !context) return

      // Replace temp items with real items
      queryClient.setQueryData<GearItem[]>(queryKeys.gearList(userId), (old) => {
        const withoutTemp = old?.filter(item => 
          !context.tempItems.some(temp => temp.id === item.id)
        ) || []
        return [...withoutTemp, ...newItems]
      })

      toast.success(
        `Successfully imported ${newItems.length} items!`,
        'Your gear has been added to your library.'
      )
    },
    onError: (error, items, context) => {
      if (!userId) return

      // Rollback on error
      if (context?.previousGear) {
        queryClient.setQueryData(queryKeys.gearList(userId), context.previousGear)
        queryClient.setQueryData<number>(queryKeys.gearCount(userId), (old) => 
          Math.max(0, (old || 0) - items.length)
        )
      }

      captureError(error as Error, {
        component: 'useBulkCreateGear',
        action: 'bulkCreate',
        metadata: { itemCount: items.length }
      })
      toast.error('Failed to import gear', 'Please try again or import fewer items at once.')
    },
    onSettled: () => {
      if (!userId) return
      // Ensure data is in sync after mutation
      queryClient.invalidateQueries({ queryKey: queryKeys.gearList(userId) })
      queryClient.invalidateQueries({ queryKey: queryKeys.gearCount(userId) })
    },
  })
}

