import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { profileRepository } from '@/lib/profileRepository'
import type { UserProfile, ProfileFormData } from '@/types/database'
import { toast } from './use-toast'

// Query key factory for profile-related queries
export const profileQueryKeys = {
  all: ['profiles'] as const,
  byUserId: (userId: string) => ['profiles', 'user', userId] as const,
  byUsername: (username: string) => ['profiles', 'username', username] as const,
  usernameAvailability: (username: string) => ['profiles', 'username-availability', username] as const,
}

// Hook to fetch a user's profile by user ID
export function useProfile(userId?: string) {
  return useQuery({
    queryKey: profileQueryKeys.byUserId(userId || ''),
    queryFn: () => profileRepository.getByUserId(userId!),
    enabled: !!userId,
    staleTime: 5 * 60 * 1000, // 5 minutes
  })
}

// Hook to fetch a public profile by username
export function usePublicProfile(username: string, enabled = true) {
  return useQuery({
    queryKey: profileQueryKeys.byUsername(username),
    queryFn: () => profileRepository.getByUsername(username),
    enabled: enabled && !!username,
    staleTime: 5 * 60 * 1000, // 5 minutes
  })
}

// Hook to check username availability
export function useCheckUsernameAvailability(username: string, excludeUserId?: string, enabled = true) {
  return useQuery({
    queryKey: profileQueryKeys.usernameAvailability(username),
    queryFn: () => profileRepository.checkUsernameAvailability(username, excludeUserId),
    enabled: enabled && !!username && username.length >= 3,
    staleTime: 30 * 1000, // 30 seconds
    gcTime: 60 * 1000, // 1 minute (formerly cacheTime)
  })
}

// Hook to create a new profile
export function useCreateProfile(userId?: string) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: (data: ProfileFormData) => {
      if (!userId) throw new Error('User ID is required to create a profile')
      return profileRepository.create({ ...data, user_id: userId })
    },
    onSuccess: (newProfile) => {
      // Invalidate and update the cache
      queryClient.invalidateQueries({ queryKey: profileQueryKeys.all })
      queryClient.setQueryData(profileQueryKeys.byUserId(newProfile.user_id), newProfile)

      toast.success('Profile created successfully!')
    },
    onError: (error: Error) => {
      toast.error(error.message || 'Failed to create profile')
    },
  })
}

// Hook to update an existing profile
export function useUpdateProfile(userId?: string) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: ({ id, updates }: { id: string; updates: Partial<ProfileFormData> }) => {
      return profileRepository.update(id, updates)
    },
    onMutate: async ({ id, updates }) => {
      // Cancel any outgoing refetches
      await queryClient.cancelQueries({ queryKey: profileQueryKeys.byUserId(userId || '') })

      // Snapshot the previous value
      const previousProfile = queryClient.getQueryData<UserProfile>(
        profileQueryKeys.byUserId(userId || '')
      )

      // Optimistically update the profile
      if (previousProfile) {
        queryClient.setQueryData(profileQueryKeys.byUserId(userId || ''), {
          ...previousProfile,
          ...updates,
        })
      }

      // Return context with snapshot
      return { previousProfile }
    },
    onError: (error: Error, _, context) => {
      // Rollback on error
      if (context?.previousProfile && userId) {
        queryClient.setQueryData(
          profileQueryKeys.byUserId(userId),
          context.previousProfile
        )
      }
      toast.error(error.message || 'Failed to update profile')
    },
    onSuccess: (updatedProfile) => {
      // Update the cache with server response
      queryClient.setQueryData(profileQueryKeys.byUserId(updatedProfile.user_id), updatedProfile)

      // Invalidate username queries if username was changed
      if (updatedProfile.username) {
        queryClient.invalidateQueries({ queryKey: ['profiles', 'username'] })
        queryClient.invalidateQueries({ queryKey: ['profiles', 'username-availability'] })
      }

      toast.success('Profile updated successfully!')
    },
    onSettled: () => {
      // Always refetch after error or success
      if (userId) {
        queryClient.invalidateQueries({ queryKey: profileQueryKeys.byUserId(userId) })
      }
    },
  })
}

// Hook to upload an avatar
export function useUploadAvatar(userId?: string) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: (file: File) => {
      if (!userId) throw new Error('User ID is required to upload avatar')
      return profileRepository.uploadAvatar(userId, file)
    },
    onSuccess: (avatarUrl) => {
      // Update the profile cache with new avatar URL
      const currentProfile = queryClient.getQueryData<UserProfile>(
        profileQueryKeys.byUserId(userId || '')
      )

      if (currentProfile) {
        queryClient.setQueryData(profileQueryKeys.byUserId(userId || ''), {
          ...currentProfile,
          avatar_url: avatarUrl,
        })
      }

      // Invalidate to ensure fresh data
      queryClient.invalidateQueries({ queryKey: profileQueryKeys.byUserId(userId || '') })

      toast.success('Avatar uploaded successfully!')
    },
    onError: (error: Error) => {
      toast.error(error.message || 'Failed to upload avatar')
    },
  })
}

// Hook to delete an avatar
export function useDeleteAvatar(userId?: string) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: (avatarUrl: string) => {
      return profileRepository.deleteAvatar(avatarUrl)
    },
    onSuccess: () => {
      // Update the profile cache to remove avatar URL
      const currentProfile = queryClient.getQueryData<UserProfile>(
        profileQueryKeys.byUserId(userId || '')
      )

      if (currentProfile) {
        queryClient.setQueryData(profileQueryKeys.byUserId(userId || ''), {
          ...currentProfile,
          avatar_url: null,
        })
      }

      // Also update the avatar URL in the database
      if (userId) {
        profileRepository.updateAvatarUrl(userId, null)
      }

      // Invalidate to ensure fresh data
      queryClient.invalidateQueries({ queryKey: profileQueryKeys.byUserId(userId || '') })

      toast.success('Avatar deleted successfully!')
    },
    onError: (error: Error) => {
      toast.error(error.message || 'Failed to delete avatar')
    },
  })
}

// Hook to validate username format (client-side)
export function useValidateUsername() {
  return (username: string): string | null => {
    if (!username) return 'Username is required'
    if (username.length < 3) return 'Username must be at least 3 characters'
    if (username.length > 30) return 'Username must be 30 characters or less'
    if (!/^[a-zA-Z]/.test(username)) return 'Username must start with a letter'
    if (!/^[a-zA-Z][a-zA-Z0-9_-]*$/.test(username)) {
      return 'Username can only contain letters, numbers, underscores, and hyphens'
    }
    return null
  }
}

