export function useUpdateProfilePrivacy(userId?: string) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async ({ profileId, settings }: { 
      profileId: string
      settings: Partial<ProfilePrivacySettings> 
    }) => {
      // For now, we only update is_public
