export function parseLighterPackHtml(html: string): ListParseResult {
  const result: ListParseResult = {
    success: false,
    list: { name: 'Imported List' },
    categories: [],
    listedGearItems: [],
    errors: [],
    warnings: [],
    metadata: {}
  }

  try {
    // Extract list name from title or h1
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i) || 
                      html.match(/<h1[^>]*>([^<]+)<\/h1>/i)

    if (titleMatch) {
      result.list.name = titleMatch[1].replace(/\s*-\s*LighterPack.*$/i, '').trim()
    }

    // Find the categories container - need to match the outermost ul with lpCategories class
    // We need to be careful because there are nested ul elements
    const categoriesMatch = html.match(/<ul[^>]*class="[^"]*lpCategories[^"]*"[^>]*>([\s\S]*)<\/ul>/i)

    if (!categoriesMatch) {
      result.errors.push('No categories container found in the LighterPack page')
      return result
    }

    // Extract just the content we need - up to the closing tag for lpCategories
    // Find the last occurrence of </ul> that matches the lpCategories level
    let categoriesHtml = categoriesMatch[1]
    // Remove any content after the categories
    const lastCategoryEnd = categoriesHtml.lastIndexOf('</li>')
    if (lastCategoryEnd > -1) {
      categoriesHtml = categoriesHtml.substring(0, lastCategoryEnd + 5)
    }

    // Now split by category - look for lpCategory list items
    // We'll use a simpler approach: split by lpCategory class
    const categoryBlocks = categoriesHtml.split(/<li[^>]*class="[^"]*lpCategory[^"]*"[^>]*>/i)

    if (categoryBlocks.length <= 1) {
      result.errors.push('No categories found in the LighterPack page')
      return result
    }

    let globalSortIndex = 0
    const categoryMap = new Map<string, number>()

    // Skip the first element (it's empty or contains content before first category)
    for (let i = 1; i < categoryBlocks.length; i++) {
      const categoryHtml = categoryBlocks[i]

      // Extract category name
      const categoryNameMatch = categoryHtml.match(/<h2[^>]*class="[^"]*lpCategoryName[^"]*"[^>]*>([^<]+)<\/h2>/i)
      if (!categoryNameMatch) continue

      const categoryName = categoryNameMatch[1].trim()

      // Add category if not already added
      if (!categoryMap.has(categoryName)) {
        result.categories.push({
          name: categoryName,
          sort_index: categoryMap.size,
          icon: null,
          color: null
        })
        categoryMap.set(categoryName, categoryMap.size)
      }

      // Look for ALL items in this category
      // Use a global match to find all lpItem elements
      const itemMatches = categoryHtml.match(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*>[\s\S]*?<\/li>/gi)

      if (itemMatches && itemMatches.length > 0) {
        for (const itemHtml of itemMatches) {
          try {
            const item = parseHtmlItem(itemHtml)
            if (item) {
              const validationErrors = validateParsedGearItem(item)
              if (validationErrors.length === 0) {
                // Check for worn flag
                const isWorn = /<i[^>]*class="[^"]*lpActive[^"]*lpWorn[^"]*"|<i[^>]*class="[^"]*lpWorn[^"]*lpActive[^"]*"[^>]*>/i.test(itemHtml)

                // Extract quantity (default to 1)
                const qtyMatch = itemHtml.match(/<span[^>]*class="[^"]*lpQty[^"]*"[^>]*>([^<]+)<\/span>/i)
                const quantity = qtyMatch ? parseInt(qtyMatch[1]) || 1 : 1

                result.listedGearItems.push({
                  gearItem: item,
                  categoryName,
                  quantity,
                  worn: isWorn,
                  sort_index: globalSortIndex++,
                  weight_g_override: null,
                  notes: null
                })
              } else {
                result.errors.push(`Invalid item in ${categoryName}: ${validationErrors.join(', ')}`)
              }
            }
          } catch (error) {
            const message = error instanceof Error ? error.message : 'Unknown error'
            result.warnings.push(`Failed to parse item in ${categoryName}: ${message}`)
          }
        }
      }
    }

    // Calculate metadata
    if (result.listedGearItems.length > 0) {
      const totalWeight = result.listedGearItems.reduce((sum, item) => {
        const weight = item.worn ? 0 : (item.weight_g_override ?? item.gearItem.weight_g)
        return sum + (weight * item.quantity)
      }, 0)

      result.metadata.totalWeight = totalWeight
      result.metadata.itemCount = result.listedGearItems.length
      result.metadata.categoryCount = result.categories.length
    }

    result.success = result.listedGearItems.length > 0

    if (result.listedGearItems.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

