  checkUsernameAvailability(username: string, excludeUserId?: string): Promise<boolean>
  uploadAvatar(userId: string, file: File): Promise<string>
  deleteAvatar(avatarUrl: string): Promise<void>
}

class ProfileRepositoryImpl implements ProfileRepository {
  async getByUserId(userId: string): Promise<UserProfile | null> {
    const { data, error } = await supabase
      .from('user_profiles')
      .select('*')
      .eq('user_id', userId)
      .single()

    if (error) {
      if (error.code === 'PGRST116') {
        // No profile found
        return null
      }
      throw new Error(`Failed to fetch profile: ${error.message}`)
    }

    return data
  }

  async getByUsername(username: string): Promise<UserProfile | null> {
    const { data, error } = await supabase
      .rpc('get_public_profile', { profile_username: username })
      .single()

    if (error) {
      if (error.code === 'PGRST116') {
        // No public profile found
        return null
      }
      throw new Error(`Failed to fetch profile by username: ${error.message}`)
    }

    // Map the public profile data to UserProfile interface
    // Note: Some fields like user_id and is_public are not returned for public profiles
    return data ? {
      ...data,
      user_id: '', // Not exposed for public profiles
      is_public: true, // Must be true if returned from get_public_profile
      updated_at: data.created_at // Public profiles don't expose updated_at
    } : null
  }

  async create(data: ProfileFormData & { user_id: string }): Promise<UserProfile> {
    const { data: profile, error } = await supabase
      .from('user_profiles')
      .insert({
        user_id: data.user_id,
        username: data.username,
        display_name: data.display_name,
        location: data.location || null,
        about_me: data.about_me || null,
        is_public: data.is_public
      })
      .select()
      .single()

    if (error) {
      if (error.code === '23505') {
        // Unique constraint violation
        if (error.message.includes('username')) {
          throw new Error('Username is already taken')
        }
        if (error.message.includes('user_id')) {
          throw new Error('Profile already exists for this user')
        }
      }
      throw new Error(`Failed to create profile: ${error.message}`)
    }

    return profile
  }

  async update(id: string, data: Partial<ProfileFormData>): Promise<UserProfile> {
    const updateData: any = {}

    // Only include fields that are being updated
    if (data.username !== undefined) updateData.username = data.username
    if (data.display_name !== undefined) updateData.display_name = data.display_name
    if (data.location !== undefined) updateData.location = data.location || null
    if (data.about_me !== undefined) updateData.about_me = data.about_me || null
    if (data.is_public !== undefined) updateData.is_public = data.is_public

    const { data: profile, error } = await supabase
      .from('user_profiles')
      .update(updateData)
      .eq('id', id)
      .select()
      .single()

    if (error) {
      if (error.code === '23505' && error.message.includes('username')) {
        throw new Error('Username is already taken')
      }
      throw new Error(`Failed to update profile: ${error.message}`)
    }

    return profile
  }

  async checkUsernameAvailability(username: string, excludeUserId?: string): Promise<boolean> {
    const { data, error } = await supabase
      .rpc('check_username_availability', {
        check_username: username,
        exclude_user_id: excludeUserId || null
      })

    if (error) {
      throw new Error(`Failed to check username availability: ${error.message}`)
    }

    return data === true
  }

  async uploadAvatar(userId: string, file: File): Promise<string> {
    // Validate file type
    const allowedTypes = ['image/jpeg', 'image/png', 'image/webp']
    if (!allowedTypes.includes(file.type)) {
      throw new Error('Invalid file type. Please upload a JPG, PNG, or WebP image.')
    }

    // Validate file size (5MB max)
    const maxSize = 5 * 1024 * 1024 // 5MB in bytes
    if (file.size > maxSize) {
      throw new Error('File size must be less than 5MB')
    }

    // Generate unique filename with timestamp
    const timestamp = Date.now()
    const fileExt = file.name.split('.').pop()
    const fileName = `${userId}/${timestamp}.${fileExt}`

    // Get the old avatar URL first (for cleanup if needed)
    const { data: profile } = await supabase
      .from('user_profiles')
      .select('avatar_url')
      .eq('user_id', userId)
      .single()

    const oldAvatarUrl = profile?.avatar_url

    // Upload to Supabase Storage
    const { error: uploadError } = await supabase.storage
      .from('avatars')
      .upload(fileName, file, {
        cacheControl: '3600',
        upsert: false
      })

    if (uploadError) {
      throw new Error(`Failed to upload avatar: ${uploadError.message}`)
    }

    // Get public URL
    const { data: { publicUrl } } = supabase.storage
      .from('avatars')
      .getPublicUrl(fileName)

    // Update profile with new avatar URL
    const { error: updateError } = await supabase
      .from('user_profiles')
      .update({ avatar_url: publicUrl })
      .eq('user_id', userId)

    if (updateError) {
      // Try to delete the uploaded file if profile update fails
      try {
        await supabase.storage.from('avatars').remove([fileName])
      } catch (cleanupError) {
        console.error('Failed to cleanup uploaded file:', cleanupError)
      }
      throw new Error(`Failed to update profile with avatar: ${updateError.message}`)
    }

    // Clean up old avatar if it exists
    if (oldAvatarUrl) {
      try {
        await this.deleteAvatar(oldAvatarUrl)
      } catch (cleanupError) {
        // Log but don't fail - old avatar cleanup is not critical
        console.error('Failed to delete old avatar:', cleanupError)
      }
    }

    return publicUrl
  }

  async deleteAvatar(avatarUrl: string): Promise<void> {
    if (!avatarUrl) return

    // Extract file path from URL
    // URL format: https://[project].supabase.co/storage/v1/object/public/avatars/[userId]/[timestamp].[ext]
    const urlParts = avatarUrl.split('/avatars/')
    if (urlParts.length !== 2) {
      throw new Error('Invalid avatar URL format')
    }

    const filePath = urlParts[1]

    const { error } = await supabase.storage
      .from('avatars')
      .remove([filePath])

    if (error) {
      throw new Error(`Failed to delete avatar: ${error.message}`)
    }
  }

  async updateAvatarUrl(userId: string, avatarUrl: string | null): Promise<void> {
    const { error } = await supabase
      .from('user_profiles')
      .update({ avatar_url: avatarUrl })
      .eq('user_id', userId)

    if (error) {
      throw new Error(`Failed to update avatar URL: ${error.message}`)
    }
  }
}

// Export singleton instance
export const profileRepository: ProfileRepository = new ProfileRepositoryImpl()

// Export factory function for testing
export function createProfileRepository(): ProfileRepository {
  return new ProfileRepositoryImpl()
}

