import * as Sentry from '@sentry/react'

let isSentryEnabled = false

export function initSentry() {
  const dsn = import.meta.env.VITE_SENTRY_DSN
  const isDevelopment = import.meta.env.MODE === 'development'
  const isProduction = import.meta.env.MODE === 'production'
  const isStaging = import.meta.env.MODE === 'staging'

  // Only initialize Sentry if we have a DSN and we're not in development
  if (dsn && !isDevelopment) {
    try {
      Sentry.init({
        dsn,
        environment: import.meta.env.MODE,
        integrations: [
          Sentry.browserTracingIntegration(),
          Sentry.replayIntegration({
            maskAllText: false,
            blockAllMedia: false,
          }),
        ],
        // Only enable tracing in production/staging
        tracesSampleRate: isProduction ? 0.1 : 0.5,
        // Only enable session replay in production/staging
        replaysSessionSampleRate: isProduction ? 0.1 : 0.5,
        replaysOnErrorSampleRate: 1.0,
        // Disable Sentry in development mode
        enabled: !isDevelopment,
        // Additional safety check to ensure we don't send events in development
        beforeSend(event) {
          if (isDevelopment) {
            return null
          }
          return event
        },
        // Configure release tracking
        release: import.meta.env.VITE_APP_VERSION || 'unknown',
        // Configure debug mode for staging
        debug: isStaging,
      })

      isSentryEnabled = true
      console.log(`Sentry initialized for ${import.meta.env.MODE} environment`)
    } catch (error) {
      console.error('Failed to initialize Sentry:', error)
      isSentryEnabled = false
    }
  } else if (isDevelopment) {
    // In development, we can optionally log that Sentry is disabled
    console.log('Sentry is disabled in development mode')
    isSentryEnabled = false
  } else if (!dsn) {
    console.log('Sentry DSN not provided, skipping initialization')
    isSentryEnabled = false
  }
}

// Utility function to check if Sentry is enabled
export function isSentryActive(): boolean {
  return isSentryEnabled
}

// Utility function to capture errors conditionally
export function captureError(error: Error, context?: Record<string, any>) {
  if (isSentryEnabled) {
    Sentry.captureException(error, { extra: context })
  } else {
    // In development, log to console instead
    console.error('Error captured (Sentry disabled):', error, context)
  }
}

// Utility function to capture messages conditionally
export function captureMessage(message: string, level: Sentry.SeverityLevel = 'info') {
  if (isSentryEnabled) {
    Sentry.captureMessage(message, level)
  } else {
    // In development, log to console instead
    console.log(`Message captured (Sentry disabled): ${message}`, { level })
  }
}

