      result.errors.push('No weight column found. Required columns: description, weight')
      return result
    }

    // Parse each row
    for (let i = 0; i < allParsedRows.length; i++) {
      const row = allParsedRows[i]
      if (row.length === 0 || row.every(cell => !cell.trim())) continue

      try {
        const item = parseRowToGearItem(row, columnMap, headers)
        const validationErrors = validateParsedGearItem(item)

        if (validationErrors.length > 0) {
          result.errors.push(`Row ${i + 2}: ${validationErrors.join(', ')}`)
          continue
        }

        result.data.push(item)
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.errors.push(`Row ${i + 2}: ${message}`)
      }
    }

    // Check for duplicates within the parsed data
    const { unique, duplicates } = findDuplicates(result.data)
    result.data = unique

    if (duplicates.length > 0) {
      result.warnings.push(`Found ${duplicates.length} potential duplicate${duplicates.length === 1 ? '' : 's'} (similar description/weight/brand)`)
    }

    result.success = result.data.length > 0
    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

function parseRow(line: string): string[] {
  const result: string[] = []
  let current = ''
  let inQuotes = false
  let i = 0

  while (i < line.length) {
    const char = line[i]

    if (char === '"') {
      if (inQuotes && line[i + 1] === '"') {
        current += '"'
        i += 2
        continue
      }
      inQuotes = !inQuotes
    } else if (char === ',' && !inQuotes) {
      result.push(current.trim())
      current = ''
    } else {
      current += char
    }
    i++
  }

  result.push(current.trim())
  return result
}

function mapColumns(headers: string[], _rows: string[][]): ColumnMap {
  const map: ColumnMap = {}

  for (const [field, possibleNames] of Object.entries(COLUMN_MAPPINGS)) {
    for (let i = 0; i < headers.length; i++) {
      const header = headers[i].toLowerCase().trim()
      if (possibleNames.some(name => header.includes(name.toLowerCase()))) {
        map[field] = i
        break
      }
    }
  }

  return map
}

function parseRowToGearItem(values: string[], columnMap: ColumnMap, headers: string[]): ParsedGearItem {
  const getValue = (field: string): string => {
    const index = columnMap[field]
    return index !== undefined ? values[index]?.trim() || '' : ''
  }

  // Check column structure for smart mapping
  const hasNameColumn = headers.some(h => ['name', 'item name', 'item', 'gear name', 'product', 'label'].includes(h.toLowerCase().trim()))
  const hasDescColumn = headers.some(h => ['description'].includes(h.toLowerCase().trim()))

  // Required fields
  const description = getValue('description')
  if (!description) {
    throw new Error('Item description is required')
  }

  const weightStr = getValue('weight')
  if (!weightStr) {
    throw new Error('Weight is required')
  }

  const { grams: weight_g, unit: weight_unit_display } = parseWeightFromText(weightStr)

  // Optional fields with fallbacks
  const brand = getValue('brand') || undefined
  const item_type = getValue('item_type') || 'Other'

  // Brand detection removed - preserve original data only

  // Keep item_type as provided in CSV, no automatic categorization

  const consumable = parseBoolean(getValue('consumable'))
  const priceStr = getValue('price')
  const price = priceStr ? parseFloat(priceStr.replace(/[$,]/g, '')) : undefined
  // Smart notes handling: 
  // If we have both name and description columns, put description content in notes
  // If we only have description column, it's already used as main description
  let notes = getValue('notes') || undefined

  if (!notes && hasNameColumn && hasDescColumn) {
    // We have separate name and description columns, so put description in notes
    notes = headers.map((h, i) => h.toLowerCase().trim() === 'description' ? values[i]?.trim() : null).find(v => v) || undefined
  }
  const url = getValue('url') || undefined

  return {
    description,
    brand: brand || null,
    model: null, // CSV rarely has model info separate from description
    weight_g,
    weight_unit_display,
    item_type,
    consumable,
    price: price || null,
    notes: notes || null,
    image_url: null, // CSV doesn't contain images
    url: url || null
  }
}

function findDuplicates(items: ParsedGearItem[]): { unique: ParsedGearItem[], duplicates: { item: ParsedGearItem, duplicateOf: number }[] } {
  const unique: ParsedGearItem[] = []
  const duplicates: { item: ParsedGearItem, duplicateOf: number }[] = []

  for (let i = 0; i < items.length; i++) {
    const currentItem = items[i]
    let isDuplicate = false

    for (let j = 0; j < unique.length; j++) {
      const existingItem = unique[j]

      // Check if descriptions match (case-insensitive)
      const descriptionsMatch = currentItem.description.toLowerCase().trim() === existingItem.description.toLowerCase().trim()

      // Check if weights are similar (within 5g)
      const weightsMatch = Math.abs(currentItem.weight_g - existingItem.weight_g) <= 5

      // Check if brands match (case-insensitive, treating null/undefined as empty)
      const brandsMatch = (currentItem.brand || '').toLowerCase().trim() === (existingItem.brand || '').toLowerCase().trim()

      if (descriptionsMatch && weightsMatch && brandsMatch) {
        duplicates.push({ item: currentItem, duplicateOf: j })
        isDuplicate = true
        break
      }
    }

    if (!isDuplicate) {
      unique.push(currentItem)
    }
  }

  return { unique, duplicates }
}

export function parseCsv(csvContent: string, listName: string = 'Imported List'): ListParseResult {
  const result: ListParseResult = {
    success: false,
    list: { name: listName },
    categories: [],
    listedGearItems: [],
    errors: [],
    warnings: []
  }

  try {
    const lines = csvContent.trim().split('\n')
    if (lines.length < 2) {
      result.errors.push('CSV must have at least a header row and one data row')
      return result
    }

    const headers = parseRow(lines[0])
    const allParsedRows = lines.slice(1).map(line => parseRow(line))

    // Create column mapping with intelligent detection
    const columnMap = mapColumns(headers, allParsedRows)

    if (columnMap.description === undefined) {
      result.errors.push('No description/item column found. Required columns: description, weight')
      return result
    }

    if (columnMap.weight === undefined) {
      result.errors.push('No weight column found. Required columns: description, weight')
      return result
    }

    // Parse all rows into items and categories
    const categoryMap = new Map<string, number>()
    let globalSortIndex = 0

    for (let i = 0; i < allParsedRows.length; i++) {
      const row = allParsedRows[i]

      // Skip empty rows
      if (row.every(cell => !cell?.trim())) {
        continue
      }

      try {
        // Parse basic item fields
        const description = row[columnMap.description!]?.trim()
        if (!description) {
          result.warnings.push(`Row ${i + 2}: Skipping empty item`)
          continue
        }

        const weightText = row[columnMap.weight!]
        const { grams, unit } = parseWeightFromText(weightText)

        // Determine category
        let categoryName = 'Imported Items' // Default category
        if (columnMap.category !== undefined) {
          categoryName = row[columnMap.category]?.trim() || categoryName
        } else if (columnMap.item_type !== undefined) {
          // Use item_type as category if no explicit category column
          categoryName = row[columnMap.item_type]?.trim() || categoryName
        }

        // Add category if new
        if (!categoryMap.has(categoryName)) {
          const sortIndex = categoryMap.size
          result.categories.push({
            name: categoryName,
            sort_index: sortIndex,
            icon: null,
            color: null
          })
          categoryMap.set(categoryName, sortIndex)
        }

        // Create the gear item
        const item: ParsedGearItem = {
          description,
          brand: columnMap.brand !== undefined ? row[columnMap.brand] || null : null,
          model: null,
          weight_g: grams,
          weight_unit_display: unit,
          item_type: columnMap.item_type !== undefined ? row[columnMap.item_type] || categoryName : categoryName,
          consumable: columnMap.consumable !== undefined ? parseBoolean(row[columnMap.consumable]) : false,
          price: columnMap.price !== undefined ? parseFloat(row[columnMap.price]?.replace(/[$,]/g, '')) || null : null,
          notes: columnMap.notes !== undefined ? row[columnMap.notes] || null : null,
          image_url: null,
          url: columnMap.url !== undefined ? row[columnMap.url] || null : null
        }

        // Validate the item
        const itemErrors = validateParsedGearItem(item)
        if (itemErrors.length > 0) {
          result.warnings.push(`Row ${i + 2}: ${itemErrors.join(', ')}`)
          continue
        }

        // Parse list-specific fields
        const quantity = columnMap.quantity !== undefined 
          ? parseInt(row[columnMap.quantity]) || 1 
          : 1
        const worn = columnMap.worn !== undefined 
          ? parseBoolean(row[columnMap.worn]) 
          : false

        // Add as listed gear item
        result.listedGearItems.push({
          gearItem: item,
          categoryName,
          quantity,
          worn,
          sort_index: globalSortIndex++,
          weight_g_override: null,
          notes: null
        })

      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.warnings.push(`Row ${i + 2}: ${message}`)
      }
    }

    // Ensure we have at least one category if we have items
    if (result.listedGearItems.length > 0 && result.categories.length === 0) {
      result.categories.push({
        name: 'Imported Items',
        sort_index: 0,
        icon: null,
        color: null
      })
    }

    result.success = result.listedGearItems.length > 0

    if (result.listedGearItems.length === 0) {
      result.errors.push('No valid items found in CSV')
    } else {
      result.warnings.push(`Imported ${result.listedGearItems.length} items across ${result.categories.length} categories`)
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

import { decode as decodeHtmlEntities } from 'he'
import { 
  type ParsedGearItem, 
  type GearParseResult,
  type ListParseResult,
  validateParsedGearItem 
} from './index'

// Legacy function for backward compatibility - converts gear only
function _parseLighterPackHtmlAsGear(html: string): GearParseResult {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: [],
    metadata: {}
  }

  try {
    // Extract list name from title or h1
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i) || 
                      html.match(/<h1[^>]*>([^<]+)<\/h1>/i)

    if (titleMatch) {
      result.metadata.listName = titleMatch[1].replace(/\s*-\s*LighterPack.*$/i, '').trim()
    }

    // Look for all lpItem elements across all categories
    const itemMatches = html.match(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*>.*?<\/li>/gis)


    if (!itemMatches || itemMatches.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
      return result
    }

    // Parse each item
    for (const itemHtml of itemMatches) {
      try {
        const item = parseHtmlItem(itemHtml)
        if (item) {
          const validationErrors = validateParsedGearItem(item)
          if (validationErrors.length === 0) {
            result.data.push(item)
          } else {
            result.errors.push(`Invalid item: ${validationErrors.join(', ')}`)
          }
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.warnings.push(`Failed to parse item: ${message}`)
      }
    }

    // Calculate metadata
    if (result.data.length > 0) {
      result.metadata.totalWeight = result.data.reduce((sum, item) => sum + item.weight_g, 0)
      result.metadata.itemCount = result.data.length
    }

    result.success = result.data.length > 0

    if (result.data.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

function parseHtmlItem(itemHtml: string): ParsedGearItem | null {
  try {
    // Extract name (item_type) from lpName span - handle both plain text and anchor tags
    const nameSpanMatch = itemHtml.match(/<span[^>]*class="[^"]*lpName[^"]*"[^>]*>(.*?)<\/span>/is)
    let name = null
    if (nameSpanMatch) {
      // Check if there's an anchor tag inside
      const anchorMatch = nameSpanMatch[1].match(/<a[^>]*>([^<]+)<\/a>/i)
      name = anchorMatch ? anchorMatch[1].trim() : nameSpanMatch[1].trim()
    }

    if (!name) {
      return null
    }

    // Extract description from lpDesc span, or anchor text within lpName
    let description = name // fallback to name

    // Try to get description from lpDescription
    const descMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDescription[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (descMatch?.[1]?.trim()) {
      description = descMatch[1].trim()
    } else {
      // Try to get from anchor text in lpName
      const anchorMatch = itemHtml.match(/<a[^>]*>([^<]+)<\/a>/i)
      if (anchorMatch?.[1]?.trim() && anchorMatch[1].trim() !== name) {
        description = anchorMatch[1].trim()
      }
    }

    // Extract URL from anchor in lpName
    const urlMatch = itemHtml.match(/<a[^>]*href="([^"]+)"/i)
    const url = urlMatch?.[1] ? decodeHtmlEntities(urlMatch[1]) : null

    // Extract weight and unit from lpWeight span and lpUnitSelect
    const weightMatch = itemHtml.match(/<span[^>]*class="[^"]*lpWeight[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (!weightMatch) return null

    const unitMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDisplay[^"]*"[^>]*>([^<]+)<\/span>/i)
    const unit = unitMatch?.[1]?.trim() || 'g'

    const weight = parseFloat(weightMatch[1])
    if (isNaN(weight)) return null

    // Convert to grams based on unit
    let weight_g: number
    switch (unit.toLowerCase()) {
      case 'oz':
        weight_g = Math.round(weight * 28.3495)
        break
      case 'lb':
        weight_g = Math.round(weight * 453.592)
        break
      case 'kg':
        weight_g = Math.round(weight * 1000)
        break
      case 'g':
      default:
        weight_g = Math.round(weight)
        break
    }

    const weight_unit_display = unit as 'g' | 'oz' | 'lb' | 'kg'


    // Check if item is consumable (must have an i element with both lpConsumable and lpActive classes)
    const consumable = /<i[^>]*class="[^"]*lpConsumable[^"]*lpActive[^"]*"[^>]*>|<i[^>]*class="[^"]*lpActive[^"]*lpConsumable[^"]*"[^>]*>/i.test(itemHtml)

    // Extract price from lpPriceCell span
    const priceMatch = itemHtml.match(/<span[^>]*class="[^"]*lpPriceCell[^"]*"[^>]*>\$?([0-9.,]+)<\/span>/i)
    const price = priceMatch ? parseFloat(priceMatch[1].replace(/[,$]/g, '')) : null

    // Use name directly as item_type (preserve original data)
    const item_type = name

    const result = {
      description: description || name, // Use description as the main field, fallback to name
      brand: null, // LighterPack doesn't separate brand info
      model: null,
      weight_g,
      weight_unit_display,
      item_type,
      consumable,
      price,
      notes: null, // LighterPack doesn't have separate notes
      image_url: null,
      url
    }

    return result

  } catch (error) {
    console.warn('Error parsing LighterPack item:', error)
    return null
  }
}

export function parseLighterPackHtml(html: string): ListParseResult {
  const result: ListParseResult = {
    success: false,
    list: { name: 'Imported List' },
    categories: [],
    listedGearItems: [],
    errors: [],
    warnings: [],
    metadata: {}
  }

  try {
    // Extract list name from title or h1
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i) || 
                      html.match(/<h1[^>]*>([^<]+)<\/h1>/i)

    if (titleMatch) {
      result.list.name = titleMatch[1].replace(/\s*-\s*LighterPack.*$/i, '').trim()
    }

    // Find the categories container - need to match the outermost ul with lpCategories class
    // We need to be careful because there are nested ul elements
    const categoriesMatch = html.match(/<ul[^>]*class="[^"]*lpCategories[^"]*"[^>]*>([\s\S]*)<\/ul>/i)

    if (!categoriesMatch) {
      result.errors.push('No categories container found in the LighterPack page')
      return result
    }

    // Extract just the content we need - up to the closing tag for lpCategories
    // Find the last occurrence of </ul> that matches the lpCategories level
    let categoriesHtml = categoriesMatch[1]
    // Remove any content after the categories
    const lastCategoryEnd = categoriesHtml.lastIndexOf('</li>')
    if (lastCategoryEnd > -1) {
      categoriesHtml = categoriesHtml.substring(0, lastCategoryEnd + 5)
    }

    // Now split by category - look for lpCategory list items
    // We'll use a simpler approach: split by lpCategory class
    const categoryBlocks = categoriesHtml.split(/<li[^>]*class="[^"]*lpCategory[^"]*"[^>]*>/i)

    if (categoryBlocks.length <= 1) {
      result.errors.push('No categories found in the LighterPack page')
      return result
    }

    let globalSortIndex = 0
    const categoryMap = new Map<string, number>()

    // Skip the first element (it's empty or contains content before first category)
    for (let i = 1; i < categoryBlocks.length; i++) {
      const categoryHtml = categoryBlocks[i]

      // Extract category name
      const categoryNameMatch = categoryHtml.match(/<h2[^>]*class="[^"]*lpCategoryName[^"]*"[^>]*>([^<]+)<\/h2>/i)
      if (!categoryNameMatch) continue

      const categoryName = categoryNameMatch[1].trim()

      // Add category if not already added
      if (!categoryMap.has(categoryName)) {
        result.categories.push({
          name: categoryName,
          sort_index: categoryMap.size,
          icon: null,
          color: null
        })
        categoryMap.set(categoryName, categoryMap.size)
      }

      // Look for ALL items in this category
      // Use a global match to find all lpItem elements
      const itemMatches = categoryHtml.match(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*>[\s\S]*?<\/li>/gi)

      if (itemMatches && itemMatches.length > 0) {
        for (const itemHtml of itemMatches) {
          try {
            const item = parseHtmlItem(itemHtml)
            if (item) {
              const validationErrors = validateParsedGearItem(item)
              if (validationErrors.length === 0) {
                // Check for worn flag
                const isWorn = /<i[^>]*class="[^"]*lpActive[^"]*lpWorn[^"]*"|<i[^>]*class="[^"]*lpWorn[^"]*lpActive[^"]*"[^>]*>/i.test(itemHtml)

                // Extract quantity (default to 1)
                const qtyMatch = itemHtml.match(/<span[^>]*class="[^"]*lpQty[^"]*"[^>]*>([^<]+)<\/span>/i)
                const quantity = qtyMatch ? parseInt(qtyMatch[1]) || 1 : 1

                result.listedGearItems.push({
                  gearItem: item,
                  categoryName,
                  quantity,
                  worn: isWorn,
                  sort_index: globalSortIndex++,
                  weight_g_override: null,
                  notes: null
                })
              } else {
                result.errors.push(`Invalid item in ${categoryName}: ${validationErrors.join(', ')}`)
              }
            }
          } catch (error) {
            const message = error instanceof Error ? error.message : 'Unknown error'
            result.warnings.push(`Failed to parse item in ${categoryName}: ${message}`)
          }
        }
      }
    }

    // Calculate metadata
    if (result.listedGearItems.length > 0) {
      const totalWeight = result.listedGearItems.reduce((sum, item) => {
        const weight = item.worn ? 0 : (item.weight_g_override ?? item.gearItem.weight_g)
        return sum + (weight * item.quantity)
      }, 0)

      result.metadata.totalWeight = totalWeight
      result.metadata.itemCount = result.listedGearItems.length
      result.metadata.categoryCount = result.categories.length
    }

    result.success = result.listedGearItems.length > 0

    if (result.listedGearItems.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

export async function parseLighterPackUrl(url: string): Promise<ListParseResult> {
  const result: ListParseResult = {
    success: false,
    list: { name: 'Imported List' },
    categories: [],
    listedGearItems: [],
    errors: [],
    warnings: []
  }

  // Validate URL format
  if (!url.match(/^https:\/\/lighterpack\.com\/r\/[a-zA-Z0-9]+$/)) {
    result.errors.push('Invalid LighterPack URL format. Expected: https://lighterpack.com/r/[ID]')
    return result
  }

  // For now, direct URL import is not implemented
  result.errors.push('Direct URL import not yet implemented. Please use CSV export from LighterPack for now.')
  return result
}

