import { test as setup, expect } from '@playwright/test'
import { createClient } from '@supabase/supabase-js'

const authFile = 'tests/.auth/user.json'

// Test user credentials from environment variables
const TEST_USER = {
  email: process.env.TEST_USER_EMAIL || 'test.e2e@example.com',
  password: process.env.TEST_USER_PASSWORD || 'TestPassword123!'
}

async function ensureTestUser() {
  try {
    const supabaseUrl = process.env.VITE_SUPABASE_URL!
    const supabaseKey = process.env.VITE_SUPABASE_ANON_KEY!

    const supabase = createClient(supabaseUrl, supabaseKey)

    // Test connection with a simple query
    const { error: connectionError } = await supabase.from('gear_items').select('count').limit(1)

    if (connectionError && !connectionError.message.includes('JWT')) {
      throw new Error(`Supabase connection failed: ${connectionError.message}`)
    }

    // Try to create the test user (will fail silently if it already exists)
    try {
      const { error: signUpError } = await supabase.auth.signUp({
        email: TEST_USER.email,
        password: TEST_USER.password,
      })

      // Ignore "User already registered" error
      if (signUpError && !signUpError.message.includes('already registered')) {
        console.log('⚠️  Test user creation warning:', signUpError.message)
      } else if (!signUpError) {
        console.log('✅ Test user created (may need email confirmation)')
      } else {
        console.log('✅ Test user already exists')
      }
    } catch (userError) {
      console.log('ℹ️  Test user setup note:', userError)
    }

    return true
  } catch (error) {
    console.error('Supabase setup failed:', error)
    return false
  }
}

setup('authenticate', async ({ page }) => {
  // Skip auth setup if we don't have Supabase credentials
  if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
    console.log('⏭️  Skipping auth setup - no Supabase credentials available')
    return
  }

  // Skip auth setup if we don't have test user credentials
  if (!process.env.TEST_USER_EMAIL || !process.env.TEST_USER_PASSWORD) {
    console.log('⚠️  Warning: Using default test credentials. Set TEST_USER_EMAIL and TEST_USER_PASSWORD for production use.')
  }

  console.log('🚀 Starting authentication setup...')

  // Test Supabase connection and ensure test user exists
  const isReady = await ensureTestUser()
  if (!isReady) {
    console.log('❌ Supabase setup failed - skipping auth setup')
    if (!process.env.CI) {
      throw new Error('Cannot connect to Supabase - check your credentials')
    }
    return
  }

  console.log('✅ Supabase connection verified and test user ready')

  try {
    // Navigate to login page directly (use existing confirmed test account)
    console.log('🔑 Logging in with test account:', TEST_USER.email)
    console.log('🔑 Password length:', TEST_USER.password.length)
    await page.goto('/login', { timeout: 10000 })
    await page.waitForLoadState('domcontentloaded')

    // Wait for the login form to be visible
    await page.waitForSelector('#email', { timeout: 5000 })

    // Fill login form
    await page.fill('#email', TEST_USER.email)
    await page.fill('#password', TEST_USER.password)

    // Submit login form
    await page.click('button[type="submit"]')

    // Wait a bit and check for any error messages
    await page.waitForTimeout(2000)

    // Check for error messages on the login page
    const errorElement = await page.locator('[role="alert"], .alert-destructive, [data-testid="error"]').first()
    if (await errorElement.isVisible()) {
      const errorText = await errorElement.textContent()
      console.log('❌ Login error message:', errorText)
    }

    console.log('📍 Current URL after login attempt:', page.url())

    // Wait a bit more for any redirects
    await page.waitForTimeout(3000)

    // Verify we're authenticated by trying to access a protected route
    await page.goto('/gear', { timeout: 10000 })
    await page.waitForTimeout(3000)

    const finalUrl = page.url()
    console.log('🎯 Final URL after auth flow:', finalUrl)

    if (finalUrl.includes('/gear') && !finalUrl.includes('/login')) {
      console.log('✅ Authentication successful! Accessing /gear page')

      // Save authenticated state
      await page.context().storageState({ path: authFile })
      console.log('💾 Authentication state saved to:', authFile)
    } else if (!finalUrl.includes('/login')) {
      // Not on login page, probably authenticated
      console.log('✅ Authentication appears successful (not on login page)')
      await page.context().storageState({ path: authFile })
    } else {
      throw new Error('Authentication failed - still being redirected to login page')
    }

  } catch (error) {
    console.error('❌ Auth setup failed:', error)
    if (process.env.CI) {
      // In CI, don't fail the test suite for auth issues
      console.log('⚠️  Continuing without authentication in CI environment')
      return
    }
    throw error
  }
})

